mapper.select:
SELECT e.id, e.entry_type, e.direction, e.credit_micros, e.balance_after_micros,
       e.source_type, e.source_id, e.occurred_at, e.expires_at, e.metadata_json
FROM commercial_ledger_entry e WHERE e.account_id = #{accountId}
AND e.entry_type = #{entryType}
ORDER BY e.occurred_at DESC, e.id DESC LIMIT #{limit}

