mapper.update:
UPDATE billing_order SET status = 'FULFILLED',
    fulfilled_at = COALESCE(fulfilled_at, #{fulfilledAt}), updated_at = #{fulfilledAt}
WHERE id = #{orderId}

UPDATE commercial_reservation
SET consumed_credit_micros = LEAST(reserved_credit_micros,
        consumed_credit_micros + #{chargeCreditMicros}),
    status = 'SETTLED', updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE entitlement_grant SET remaining_micros = remaining_micros - #{creditMicros},
    updated_at = #{updatedAt}
WHERE id = #{grantId} AND remaining_micros >= #{creditMicros}
